"""Run this single cell/script in Kaggle. Inputs: all MM-Fit RGB videos and CSVs.

Internet is required only for runtime/package/model installation. Pose inference uses
CPU. This prepares data and checkpoints; it does not train an exercise classifier.
"""
from pathlib import Path
import base64
import hashlib
import io
import json
import os
import shutil
import subprocess
import sys
import urllib.request
import zipfile

PAYLOAD = ''
WORKER = ''
DECISIONS = ''


def bootstrap():
    input_root = Path(os.environ.get('MOTIONLAB_INPUT', '/kaggle/input'))
    root = Path(os.environ.get('MOTIONLAB_OUTPUT', '/kaggle/working/motionlab_pipeline'))
    tools = root.parent / 'motionlab_recovery_tools'
    if not input_root.is_dir():
        raise ValueError(f'Input directory missing: {input_root}')
    # Fail before any downloads or pose processing when a video/CSV is missing.
    import re
    files = sorted(p for p in input_root.rglob('*') if p.is_file())
    errors = []
    for number in range(21):
        session = f'w{number:02d}'
        pattern = re.compile(rf'^{session}_rgb(?: \(\d+\))?\.mp4$', re.I)
        videos = set(p.resolve() for p in files if pattern.fullmatch(p.name))
        labels = [p for p in files if p.name.lower() == session + '_labels.csv']
        if len(videos) != 1 or not labels:
            errors.append(f'{session}: {len(videos)} RGB videos, {len(labels)} label CSVs')
        elif len({hashlib.sha256(p.read_bytes()).hexdigest() for p in labels}) > 1:
            errors.append(f'{session}: conflicting duplicate label CSVs')
    if errors:
        raise ValueError('Input preflight failed; no extraction started:\n'+'\n'.join(errors))
    tools.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as bundle:
        for member in bundle.infolist():
            target = (tools / member.filename).resolve()
            if not target.is_relative_to(tools.resolve()):
                raise ValueError('Invalid embedded archive path')
            if member.is_dir():
                continue
            data = bundle.read(member)
            if target.exists() and target.read_bytes() != data:
                raise ValueError(f'Tools changed: {target}; retain the old root and choose a new tools location')
            target.parent.mkdir(parents=True, exist_ok=True)
            if not target.exists():
                target.write_bytes(data)
    worker = tools / 'scripts/kaggle_recovery_worker.py'
    worker.write_bytes(base64.b64decode(WORKER))
    decisions = tools / 'review_decisions.json'
    decisions.write_bytes(base64.b64decode(DECISIONS))
    env = os.environ.copy()
    env['MPLBACKEND'] = 'Agg'
    env['PYTHONPATH'] = str(tools / 'src')
    env['PYTHONUNBUFFERED'] = '1'
    # Always use a disposable executable runtime under /tmp, avoiding restored
    # /kaggle/working executables and notebook-kernel ABI/backend conflicts.
    runtime = Path('/tmp/motionlab_runtime')
    python = runtime / 'bin/python'
    probe = None
    if python.is_file():
        try:
            probe = subprocess.run([str(python), '-c',
                'import sys,mediapipe,numpy,cv2,pytest; '
                'assert sys.version_info[:2]==(3,12); '
                'assert mediapipe.__version__=="0.10.21"; '
                'assert numpy.__version__=="1.26.4"; '
                'assert cv2.__version__=="4.11.0"; '
                'assert pytest.__version__=="8.3.5"'],
                env=env,capture_output=True,timeout=90)
        except (OSError, subprocess.TimeoutExpired):
            probe = None
    if probe is None or probe.returncode:
        manager = Path('/tmp/motionlab_uv_bootstrap')
        subprocess.run([sys.executable,'-m','pip','install','--upgrade',
            '--target',str(manager),'uv'],check=True)
        uv_env = env.copy()
        uv_env.update(PYTHONPATH=str(manager), UV_PYTHON_INSTALL_DIR='/tmp/motionlab_managed_python',
            UV_CACHE_DIR='/tmp/motionlab_uv_cache', UV_PYTHON_PREFERENCE='only-managed')
        def uv(*arguments):
            subprocess.run([sys.executable,'-m','uv',*arguments],env=uv_env,check=True)
        uv('python','install','3.12')
        if runtime.exists():
            # Preserve a failed runtime for diagnosis, without recursive deletion.
            import uuid
            runtime.rename(runtime.with_name('motionlab_runtime_old_'+uuid.uuid4().hex))
        uv('venv','--python','3.12',str(runtime))
        uv('pip','install','--python',str(python),'-r',str(tools/'requirements-ml.txt'))
    model = tools / 'assets/pose_landmarker_lite.task'
    model.parent.mkdir(exist_ok=True)
    if not model.exists():
        attached = [p for p in files if p.name == model.name]
        if len({hashlib.sha256(p.read_bytes()).hexdigest() for p in attached}) > 1:
            raise ValueError('Conflicting attached MediaPipe models')
        if attached:
            shutil.copy2(attached[0], model)
        else:
            print('Downloading official MediaPipe Lite model...',flush=True)
            url = ('https://storage.googleapis.com/mediapipe-models/pose_landmarker/'
                'pose_landmarker_lite/float16/1/pose_landmarker_lite.task')
            temporary = model.with_suffix('.download')
            with urllib.request.urlopen(url,timeout=120) as response, temporary.open('wb') as handle:
                shutil.copyfileobj(response, handle)
            temporary.replace(model)
    root.mkdir(parents=True,exist_ok=True)
    print('Verifying runtime, model and feature tests...',flush=True)
    import tempfile
    with (root/'runtime_diagnostics.log').open('a') as diagnostic:
        tests = subprocess.run([str(python),'-m','pytest',str(tools/'tests/test_ml_data.py'),
            '-q','-p','no:cacheprovider','--basetemp',tempfile.mkdtemp(prefix='motionlab_tests_')],
            env=env,stderr=diagnostic)
        if tests.returncode:
            raise RuntimeError(f'Tests failed. See {root}/runtime_diagnostics.log')
        model_check = subprocess.run([str(python),'-c',
            'from motionlab.pose import PoseEstimator; import sys; '
            'p=PoseEstimator(sys.argv[1]);p.close();print("Model initialization passed")',str(model)],
            env=env,stderr=diagnostic)
        if model_check.returncode:
            raise RuntimeError(f'Model check failed. See {root}/runtime_diagnostics.log')
    with (root/'mediapipe_warnings.log').open('a') as log:
        result = subprocess.run([str(python),'-u',str(worker),'--tools',str(tools),
            '--input',str(input_root),'--root',str(root),'--reviews',str(decisions)],env=env,stderr=log)
    if result.returncode:
        print((root/'mediapipe_warnings.log').read_text(errors='replace')[-10000:])
        raise RuntimeError('Preparation stopped. Completed caches remain reusable; rerun this same cell.')
    backup = root.parent/'motionlab_pipeline_checkpoint.zip'
    try:
        from IPython.display import display, FileLink
        display(FileLink(str(backup)))
    except ImportError:
        print(backup)


if __name__ == '__main__':
    bootstrap()
